mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM companies company
    WHERE company.code = #{code}
)

mapper.update:
UPDATE companies
SET name = #{name},
    updated_by = #{updatedBy}
WHERE id = #{companyId}
    AND is_deleted = FALSE

UPDATE companies
SET is_deleted = TRUE,
    updated_by = #{updatedBy}
WHERE id = #{companyId}
    AND is_deleted = FALSE
